import{_ as t,o as a,c as u,a5 as l}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"vue2中watch如何在页面渲染完成后执行","description":"在 Vue 2 中，如果你想让 watch 在页面渲染完成后执行，可以使用 Vue 的 nextTick 函数来实现这个目的。nextTick 用于在下一个 DOM 更新循环之后延迟执行回调函数。这样就可以确保 watch 在渲染完成后执行。以下是一个示例： \\\\<template。","frontmatter":{"title":"vue2中watch如何在页面渲染完成后执行","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在 Vue 2 中，如果你想让 watch 在页面渲染完成后执行，可以使用 Vue 的 nextTick 函数来实现这个目的。nextTick 用于在下一个 DOM 更新循环之后延迟执行回调函数。这样就可以确保 watch 在渲染完成后执行。以下是一个示例： \\\\<template。","sidebarWeight":36,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/侦听属性/vue2中watch如何在页面渲染完成后执行.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/侦听属性/vue2中watch如何在页面渲染完成后执行.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/侦听属性/vue2中watch如何在页面渲染完成后执行.md"}'),s={name:"posts/Vue系统教程/02-模板、组件与交互/侦听属性/vue2中watch如何在页面渲染完成后执行.md"};function p(o,e,c,i,n,d){return a(),u("div",null,[...e[0]||(e[0]=[l('<div><h1 id="vue2中watch如何在页面渲染完成后执行" tabindex="-1">vue2中watch如何在页面渲染完成后执行 <a class="header-anchor" href="#vue2中watch如何在页面渲染完成后执行" aria-label="Permalink to &quot;vue2中watch如何在页面渲染完成后执行&quot;">​</a></h1><blockquote><p>本节目标：理解“vue2中watch如何在页面渲染完成后执行”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 2 中，如果你想让 watch 在页面渲染完成后执行，可以使用 Vue 的 nextTick 函数来实现这个目的。nextTick 用于在下一个 DOM 更新循环之后延迟执行回调函数。这样就可以确保 watch 在渲染完成后执行。以下是一个示例：</p></blockquote><p>&lt;template&gt; &lt;div&gt; &lt;input v-model=&quot;inputValue&quot; /&gt; &lt;p&gt;{{ message }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt;</p><p>&lt;script&gt; export default { data() { return { inputValue: &#39;&#39;, message: &#39;&#39;, }; }, watch: { inputValue(newVal, oldVal) { this.$nextTick(() =&gt; { // 确保在 DOM 更新后执行 this.updateMessage(newVal, oldVal); }); }, }, methods: { updateMessage(newVal, oldVal) { this.message = <code>新值：${newVal}，旧值：${oldVal}</code>; }, }, }; &lt;/script&gt; 在这个示例中，我们创建了一个包含文本输入框和一个段落的组件。我们使用 watch 来监视 inputValue 数据属性的变化。每当 inputValue 发生变化时，我们都会调用 updateMessage 方法，但是我们将其包装在 this.$nextTick 函数中，以确保它在 DOM 更新完成后执行。这样一来，我们就可以确保 message 在页面渲染完成后更新。</p><p>在 Vue 3 中，要在页面渲染完成后执行 watch，您可以使用 Vue 的 nextTick 函数和新的 Composition API。以下是一个使用 Vue 3 和 Composition API 的示例：</p><p>html Copy code &lt;template&gt; &lt;div&gt; &lt;input v-model=&quot;inputValue&quot; /&gt; &lt;p&gt;{{ message }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt;</p><p>&lt;script&gt; import { ref, watch, nextTick } from &#39;vue&#39;;</p><p>export default { setup() { const inputValue = ref(&#39;&#39;); const message = ref(&#39;&#39;);</p><p>watch(inputValue, (newVal, oldVal) =&gt; { nextTick(() =&gt; { // 确保在 DOM 更新后执行 updateMessage(newVal, oldVal); }); });</p><p>function updateMessage(newVal, oldVal) { message.value = <code>新值：${newVal}，旧值：${oldVal}</code>; }</p><p>return { inputValue, message, }; }, }; &lt;/script&gt; 在这个 Vue 3 示例中，我们使用了 Composition API 的 setup 函数和 ref、watch、nextTick 从 &#39;vue&#39; 中导入。我们创建了两个响应式引用（inputValue 和 message），并使用 watch 来监视 inputValue 的变化。当 inputValue 发生变化时，我们将调用 updateMessage 函数，并使用 nextTick 确保它在 DOM 更新完成后执行。这样，我们可以确保 message 在页面渲染完成后更新。</p></div>',1)])])}const g=t(s,[["render",p]]);export{r as __pageData,g as default};
